import { createReadStream } from 'node:fs';
import { appendFile, mkdir, readFile, rename, writeFile, unlink } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { createInterface } from 'node:readline';
import { randomUUID } from 'node:crypto';

async function* lines(path) {
  const stream = createReadStream(path, { encoding: 'utf8' });
  const reader = createInterface({ input: stream, crlfDelay: Infinity });
  try {
    for await (const line of reader) yield line;
  } finally {
    reader.close();
    stream.destroy();
  }
}

function identity(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record) ||
      typeof record.tenant !== 'string' || !Number.isSafeInteger(record.seq)) {
    throw new Error('Event must have a string tenant and an integer seq');
  }
  return JSON.stringify([record.tenant, record.seq]);
}

async function saveCheckpoint(path, nextLine) {
  const temporary = `${path}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, JSON.stringify({ nextLine }) + '\n', { flag: 'wx' });
    await rename(temporary, path);
  } finally {
    await unlink(temporary).catch(error => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
}

export async function processBatch({ inputPath, outputPath, checkpointPath, batchSize = 4 }) {
  if (!Number.isSafeInteger(batchSize) || batchSize <= 0) {
    throw new RangeError('batchSize must be a positive safe integer');
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await mkdir(dirname(checkpointPath), { recursive: true });
  let nextLine = 0;
  let checkpointText;
  try {
    checkpointText = await readFile(checkpointPath, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (checkpointText !== undefined) {
    try {
      const checkpoint = JSON.parse(checkpointText);
      if (!Number.isSafeInteger(checkpoint?.nextLine) || checkpoint.nextLine < 0) {
        throw new Error('Invalid checkpoint');
      }
      nextLine = checkpoint.nextLine;
    } catch {
      const recovery = join(dirname(checkpointPath), 'recovery');
      await mkdir(recovery, { recursive: true });
      // Keep earlier recovery evidence too, if recovery has already occurred.
      const backup = join(recovery, 'checkpoint.bad.json');
      try {
        await readFile(backup);
        await rename(backup, join(recovery, `checkpoint.bad.${randomUUID()}.json`));
      } catch (error) {
        if (error.code !== 'ENOENT') throw error;
      }
      await rename(checkpointPath, backup);
    }
  }

  const seen = new Set();
  let needsNewline = false;
  try {
    for await (const line of lines(outputPath)) {
      if (line.trim()) seen.add(identity(JSON.parse(line)));
    }
    // Appending to an existing unterminated record must not join two records.
    const { open } = await import('node:fs/promises');
    const file = await open(outputPath, 'r');
    try {
      const { size } = await file.stat();
      if (size) {
        const last = Buffer.alloc(1);
        await file.read(last, 0, 1, size - 1);
        needsNewline = last[0] !== 10;
      }
    } finally {
      await file.close();
    }
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }

  let accepted = 0, rejected = 0, duplicates = 0, lineNumber = 0;
  for await (const line of lines(inputPath)) {
    if (lineNumber++ < nextLine) continue;
    let key;
    try {
      key = identity(JSON.parse(line));
    } catch {
      await appendFile(join(dirname(outputPath), 'rejected.ndjson'), line + '\n');
      rejected++;
      nextLine = lineNumber;
      continue;
    }
    if (seen.has(key)) {
      duplicates++;
    } else {
      await appendFile(outputPath, (needsNewline ? '\n' : '') + line + '\n');
      needsNewline = false;
      seen.add(key);
      accepted++;
    }
    nextLine = lineNumber;
    if (accepted === batchSize) break;
  }
  await saveCheckpoint(checkpointPath, nextLine);
  return { accepted, rejected, duplicates, nextLine };
}

// Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]
import { processBatch } from '../src/ingest.mjs';

const args = process.argv.slice(2);
if (args.length < 3 || args.length > 4) {
  console.error('Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]');
  process.exitCode = 1;
} else {
  const [inputPath, outputPath, checkpointPath, size] = args;
  try {
    const report = await processBatch({
      inputPath, outputPath, checkpointPath,
      ...(size === undefined ? {} : { batchSize: Number(size) }),
    });
    console.log(JSON.stringify(report));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { processBatch } from '../src/ingest.mjs';

test('default batch, identity, quarantine, resume and corrupt recovery', async () => {
  const dir = await mkdtemp(join(process.cwd(), '.resume-'));
  try {
    const options = {
      inputPath: join(dir, 'input.ndjson'),
      outputPath: join(dir, 'output.ndjson'),
      checkpointPath: join(dir, 'checkpoint.json'),
    };
    const records = [
      { tenant: 'a', seq: 1, extra: true },
      { tenant: 'b', seq: 1 },
      { tenant: 'a', seq: 2 },
      { tenant: 'a', seq: 3 },
      { tenant: 'a', seq: 4 },
    ];
    await writeFile(options.inputPath, [JSON.stringify(records[0]), 'broken',
      JSON.stringify(records[0]), ...records.slice(1).map(JSON.stringify)].join('\n'));
    assert.deepEqual(await processBatch(options),
      { accepted: 4, rejected: 1, duplicates: 1, nextLine: 6 });
    assert.deepEqual(await processBatch(options),
      { accepted: 1, rejected: 0, duplicates: 0, nextLine: 7 });
    assert.deepEqual(await processBatch(options),
      { accepted: 0, rejected: 0, duplicates: 0, nextLine: 7 });
    assert.equal(await readFile(join(dir, 'rejected.ndjson'), 'utf8'), 'broken\n');
    await writeFile(options.checkpointPath, 'corrupt');
    assert.deepEqual(await processBatch(options),
      { accepted: 0, rejected: 1, duplicates: 6, nextLine: 7 });
    assert.equal(await readFile(join(dir, 'recovery/checkpoint.bad.json'), 'utf8'), 'corrupt');
    assert.deepEqual((await readFile(options.outputPath, 'utf8')).trim().split('\n').map(JSON.parse), records);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

